query.query:
mutation UpsertWorkOrderFromCmms($objects: [work_orders_insert_input!]!) {
  insert_work_orders(
    objects: $objects,
    on_conflict: {
      constraint: work_orders_cmms_wo_id_key,
      update_columns: [
        lifecycle_phase,
        symptom_note,
        cause_note,
        action_note,
        actual_start_at,
        completed_at
      ]
    }
  ) {
    returning {
      id
      equipment_id
      lifecycle_phase
      cmms_wo_id
    }
  }
}
